                bad = True
                break
            if err not in (0, 109, 234):
                bad = True
                break
            if len(stored) + len(data) > limit:
                room = limit - len(stored)
                if room:
                    stored += data[:room]
                overflow = True
                overflow_event.set()
                break
            if data:
                stored += data
            if err == 109 or err == 0 and not data:
